#include <iostream>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, m;
    cin >> n >> m;

    i128 cycle = (i128)n * (n + 1) / 2;
    int64 remainder = cycle > m ? m : (int64)((i128)m % cycle);

    int64 low = 0, high = n;
    while (low < high) {
        int64 mid = low + (high - low + 1) / 2;
        i128 sum = (i128)mid * (mid + 1) / 2;
        if (sum <= remainder)
            low = mid;
        else
            high = mid - 1;
    }

    int64 used = (int64)((i128)low * (low + 1) / 2);
    cout << remainder - used << '\n';

    return 0;
}

